package main

import (
 "database/sql"
 "net/http"
 "strconv"
 "strings"
)

func (a *App) transfers(w http.ResponseWriter,r *http.Request,parts []string){org:=currentOrgID(r,a.orgID)
 if len(parts)==1&&r.Method==http.MethodGet{a.listTransfers(w,r,org);return}
 if len(parts)==1&&r.Method==http.MethodPost{
  var in struct{Source string `json:"source_account_id"`;Destination string `json:"destination_account_id"`;Amount int64 `json:"amount"`;Currency string `json:"currency"`;Reference string `json:"reference"`}
  if decode(r,&in)!=nil||in.Amount<=0||in.Source==""||in.Destination==""||in.Source==in.Destination||len(in.Currency)!=3||in.Reference==""{bad(w,r,"source, destination, positive amount, currency and reference are required");return}
  idemKey,hash,err:=requireIdempotencyKey(r);if err!=nil{bad(w,r,err.Error());return};tx,err:=a.db.BeginTx(r.Context(),&sql.TxOptions{Isolation:sql.LevelSerializable});if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer tx.Rollback()
  status,body,replay,err:=reserveIdempotency(r.Context(),tx,org,idemKey,hash);if err!=nil{idempotencyFailure(w,r,err);return};if replay{writeRawJSON(w,status,body);return}
  var srcCur,dstCur string;err=tx.QueryRowContext(r.Context(),`SELECT currency FROM accounts WHERE id=$1 AND organization_id=$2 AND status='active' FOR UPDATE`,in.Source,org).Scan(&srcCur);if err!=nil{notFound(w,r);return};err=tx.QueryRowContext(r.Context(),`SELECT currency FROM accounts WHERE id=$1 AND organization_id=$2 AND status='active' FOR UPDATE`,in.Destination,org).Scan(&dstCur);if err!=nil{notFound(w,r);return}
  currency:=strings.ToUpper(in.Currency);if srcCur!=currency||dstCur!=currency{bad(w,r,"account currency mismatch");return}
  var balance,reserved int64;err=tx.QueryRowContext(r.Context(),`SELECT COALESCE(SUM(CASE side WHEN 'credit' THEN amount_minor ELSE -amount_minor END),0) FROM journal_lines WHERE organization_id=$1 AND account_id=$2`,org,in.Source).Scan(&balance);if err==nil{err=tx.QueryRowContext(r.Context(),`SELECT COALESCE(SUM(amount_minor),0) FROM transfers WHERE organization_id=$1 AND source_account_id=$2 AND status='pending_approval'`,org,in.Source).Scan(&reserved)};if err!=nil||balance-reserved<in.Amount{writeJSON(w,409,problem{Error:"insufficient available funds"});return}
  threshold,_:=strconv.ParseInt(env("TRANSFER_APPROVAL_THRESHOLD_MINOR","100000000"),10,64);needsApproval:=threshold>0&&in.Amount>=threshold;state:="completed";httpStatus:=201;if needsApproval{state="pending_approval";httpStatus=202}
  id:="trf_"+newID();entry:="jrn_"+newID();actor:=principalFrom(r)
  _,err=tx.ExecContext(r.Context(),`INSERT INTO transfers(id,organization_id,source_account_id,destination_account_id,amount_minor,currency,status,reference,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`,id,org,in.Source,in.Destination,in.Amount,currency,state,in.Reference,nullable(actor.userID));if err!=nil{writeJSON(w,409,problem{Error:"transfer could not be created; reference may already exist"});return}
  if !needsApproval{
   _,err=tx.ExecContext(r.Context(),`INSERT INTO journal_entries(id,organization_id,reference_type,reference_id,currency,amount_minor) VALUES($1,$2,'transfer',$3,$4,$5)`,entry,org,id,currency,in.Amount)
   if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO journal_lines(journal_entry_id,organization_id,account_id,side,amount_minor,currency) VALUES($1,$2,$3,'debit',$5,$6),($1,$2,$4,'credit',$5,$6)`,entry,org,in.Source,in.Destination,in.Amount,currency)}
  }
  eventType:="transfer.completed";if needsApproval{eventType="transfer.approval_required"};if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO outbox_events(id,organization_id,aggregate_type,aggregate_id,event_type,payload) VALUES($1,$2,'transfer',$3,$4,jsonb_build_object('transfer_id',$3::text,'status',$5::text,'amount',$6::bigint,'currency',$7::text))`,"evt_"+newID(),org,id,eventType,state,in.Amount,currency)}
  if err!=nil{writeJSON(w,500,problem{Error:"transfer posting failed"});return};result:=map[string]any{"id":id,"status":state,"transfer_type":"internal","amount":in.Amount,"currency":currency,"reference":in.Reference};if err=storeIdempotency(r.Context(),tx,org,idemKey,httpStatus,result);err!=nil{idempotencyFailure(w,r,err);return};if err=tx.Commit();err!=nil{writeJSON(w,409,problem{Error:"transfer conflict; retry safely"});return};writeJSON(w,httpStatus,result);return
 }
 if len(parts)==2&&r.Method==http.MethodGet{var id,status,currency,reference string;var amount int64;err:=a.db.QueryRowContext(r.Context(),`SELECT id,status,currency,reference,amount_minor FROM transfers WHERE id=$1 AND organization_id=$2`,parts[1],org).Scan(&id,&status,&currency,&reference,&amount);if err==sql.ErrNoRows{notFound(w,r)}else if err!=nil{writeJSON(w,500,problem{Error:"database error"})}else{writeJSON(w,200,map[string]any{"id":id,"status":status,"currency":currency,"reference":reference,"amount":amount})};return};notFound(w,r)
}

func (a *App) reviewTransfer(w http.ResponseWriter,r *http.Request,id,action string){p:=principalFrom(r);if p.userID==""{writeJSON(w,403,problem{Error:"a distinct authenticated user must approve transfers"});return};key,hash,err:=requireIdempotencyKey(r);if err!=nil{bad(w,r,err.Error());return};org:=currentOrgID(r,a.orgID);tx,err:=a.db.BeginTx(r.Context(),&sql.TxOptions{Isolation:sql.LevelSerializable});if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer tx.Rollback();status,body,replay,err:=reserveIdempotency(r.Context(),tx,org,key,hash);if err!=nil{idempotencyFailure(w,r,err);return};if replay{writeRawJSON(w,status,body);return}
 var source,destination,currency,state string;var amount int64;var creator sql.NullString;err=tx.QueryRowContext(r.Context(),`SELECT source_account_id,destination_account_id,currency,status,amount_minor,created_by FROM transfers WHERE id=$1 AND organization_id=$2 FOR UPDATE`,id,org).Scan(&source,&destination,&currency,&state,&amount,&creator);if err==sql.ErrNoRows{notFound(w,r);return};if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};if state!="pending_approval"{writeJSON(w,409,problem{Error:"transfer is not awaiting approval"});return};if creator.Valid&&creator.String==p.userID{writeJSON(w,403,problem{Error:"initiator cannot approve their own transfer"});return}
 decision:="approved";newStatus:="completed";result:=map[string]any{"id":id,"status":newStatus};if action=="reject"{decision="rejected";newStatus="rejected";result["status"]=newStatus}
 if decision=="approved"{var c string;err=tx.QueryRowContext(r.Context(),`SELECT currency FROM accounts WHERE id=$1 AND organization_id=$2 AND status='active' FOR UPDATE`,source,org).Scan(&c);if err!=nil||strings.TrimSpace(c)!=strings.TrimSpace(currency){writeJSON(w,409,problem{Error:"source account is unavailable or currency changed"});return};err=tx.QueryRowContext(r.Context(),`SELECT currency FROM accounts WHERE id=$1 AND organization_id=$2 AND status='active' FOR UPDATE`,destination,org).Scan(&c);if err!=nil||strings.TrimSpace(c)!=strings.TrimSpace(currency){writeJSON(w,409,problem{Error:"destination account is unavailable or currency changed"});return};var balance,otherReserved int64;err=tx.QueryRowContext(r.Context(),`SELECT COALESCE(SUM(CASE side WHEN 'credit' THEN amount_minor ELSE -amount_minor END),0) FROM journal_lines WHERE organization_id=$1 AND account_id=$2`,org,source).Scan(&balance);if err==nil{err=tx.QueryRowContext(r.Context(),`SELECT COALESCE(SUM(amount_minor),0) FROM transfers WHERE organization_id=$1 AND source_account_id=$2 AND status='pending_approval' AND id<>$3`,org,source,id).Scan(&otherReserved)};if err!=nil||balance-otherReserved<amount{writeJSON(w,409,problem{Error:"insufficient available funds at approval"});return};entry:="jrn_"+newID();_,err=tx.ExecContext(r.Context(),`INSERT INTO journal_entries(id,organization_id,reference_type,reference_id,currency,amount_minor) VALUES($1,$2,'transfer',$3,$4,$5)`,entry,org,id,currency,amount);if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO journal_lines(journal_entry_id,organization_id,account_id,side,amount_minor,currency) VALUES($1,$2,$3,'debit',$5,$6),($1,$2,$4,'credit',$5,$6)`,entry,org,source,destination,amount,currency)}}
 if err==nil{_,err=tx.ExecContext(r.Context(),`UPDATE transfers SET status=$3 WHERE id=$1 AND organization_id=$2`,id,org,newStatus)};if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO transfer_approvals(id,organization_id,transfer_id,approver_user_id,decision) VALUES($1,$2,$3,$4,$5)`,"apv_"+newID(),org,id,p.userID,decision)};eventType:="transfer.approved";if decision=="rejected"{eventType="transfer.rejected"};if err==nil{_,err=tx.ExecContext(r.Context(),`INSERT INTO outbox_events(id,organization_id,aggregate_type,aggregate_id,event_type,payload) VALUES($1,$2,'transfer',$3,$4,jsonb_build_object('transfer_id',$3::text,'status',$5::text))`,"evt_"+newID(),org,id,eventType,newStatus)};if err!=nil{writeJSON(w,500,problem{Error:"transfer review failed"});return};if err=storeIdempotency(r.Context(),tx,org,key,200,result);err!=nil{idempotencyFailure(w,r,err);return};if err=tx.Commit();err!=nil{writeJSON(w,409,problem{Error:"transfer review conflict"});return};writeJSON(w,200,result)
}
